const { NODE_STATUS } = require('./lib/constants')
const Rabbitmq = require('./lib/Rabbitmq')


module.exports = function (RED) {
  function RabbitmqOut(
    config
  ) {
    let reconnectTimeout;
    let reconnect = null;
    let connection = null;
    let channel = null;
	let me = this;

    RED.events.once('flows:stopped', () => {
      clearTimeout(reconnectTimeout)
    })

    RED.nodes.createNode(this, config)
    this.status(NODE_STATUS.Disconnected)
    
    const configRabbitmq = config;

    const rabbitmq = new Rabbitmq(RED, this, configRabbitmq)

    const reconnectOnError = configRabbitmq.reconnectOnError;


    // handle input event;
    const inputListener = async (msg, _, done) => {
      const { payload, routingKey, properties: msgProperties } = msg
      const {
        exchangeRoutingKey,
        exchangeRoutingKeyType,
        rabbitmqProperties,
      } = config

      // message properties override config properties
      let properties;
      try {
        properties = {
          ...JSON.parse(rabbitmqProperties),
          ...msgProperties,
        }
      } catch (e) {
        properties = msgProperties
      }

      switch (exchangeRoutingKeyType) {
        case 'msg':
        case 'flow':
        case 'global':
          rabbitmq.setRoutingKey(
            RED.util.evaluateNodeProperty(
              exchangeRoutingKey,
              exchangeRoutingKeyType,
              this,
              msg,
            ),
          )
          break
        case 'jsonata':
          rabbitmq.setRoutingKey(
            RED.util.evaluateJSONataExpression(
              RED.util.prepareJSONataExpression(exchangeRoutingKey, this),
              msg,
            ),
          )
          break
        case 'str':
        default:
          if (routingKey) {
            // if incoming payload contains a routingKey value
            // override our string value with it.

            // Superfluous (and possibly confusing) at this point
            // but keeping it to retain backwards compatibility
            rabbitmq.setRoutingKey(routingKey)
          }
          break
      }

      if (!!properties?.headers?.doNotStringifyPayload) {
        rabbitmq.publish(payload, properties)
      } else {
        rabbitmq.publish(JSON.stringify(payload), properties)
      }

      done && done()
    }

    this.on('input', inputListener)
    // When the node is re-deployed
    this.on('close', async (done) => {
      await rabbitmq.close()
      done && done()
    })

    async function initializeNode(nodeIns) {
      reconnect = async () => {
        // check the channel and clear all the event listener
		try {
        if (channel && channel.removeAllListeners) {
          channel.removeAllListeners()
			  channel.close()
				.catch(err => {
					me.error('Error closing channel:', err);
				});

			  //channel = null;
			}
		} catch (error) {
		  // catch and suppress error
		  me.error('Error occurred:', error);
		}
          channel = null;
		
		try {
        // check the connection and clear all the event listener
        if (connection && connection.removeAllListeners) {
          connection.removeAllListeners()
			  connection.close()
				.catch(err => {
					me.error('Error closing connection:', err);
				});
			  //connection = null;
			}
		} catch (error) {
		  // catch and suppress error
		  me.error('Error occurred:', error);
		}
          connection = null;

        // always clear timer before set it;
        clearTimeout(reconnectTimeout);
        reconnectTimeout = setTimeout(() => {
          try {
            initializeNode(nodeIns)
          } catch (e) {
            reconnect()
          }
        }, 2000)
      }
  
      try {
        const connection = await rabbitmq.connect()

        // istanbul ignore else
        if (connection) {
          channel = await rabbitmq.initialize()

          // When the server goes down
          connection.on('close', async e => {
            e && (await reconnect())
          })
          
          // When the connection goes down
          connection.on('error', async e => {
            reconnectOnError && (await reconnect())
            nodeIns.error(`Connection error ${e}`, { payload: { error: e, location: 'ConnectionErrorEvent' } })
          })

          // When the channel goes down
          channel.on('close', async () => {
            await reconnect()
          })

          // When the channel error occur
          channel.on('error', async e => {
            reconnectOnError && (await reconnect())
            nodeIns.error(`Channel error ${e}`, { payload: { error: e, location: 'ChannelErrorEvent' } })
          })
          
          nodeIns.status(NODE_STATUS.Connected)
        }
      } catch (e) {
        reconnectOnError && (await reconnect())
        if (e.code === 'ENOTFOUND') {
          nodeIns.status(NODE_STATUS.Invalid)
          nodeIns.error(`RabbitmqOut() Could not connect to broker ${e}`, { payload: { error: e, location: 'ConnectError' } })
        } else {
          nodeIns.status(NODE_STATUS.Error)
          nodeIns.error(`RabbitmqOut() ${e}`, { payload: { error: e, location: 'ConnectError' } })
        }
      }
    }

    // call
    initializeNode(this);
  }
  RED.nodes.registerType('rabbitmq-out', RabbitmqOut)
}